#include "magick_api.h"

size_t RegisterMPCImage(void) {
    MagickInfo* info = AcquireMagickInfo("MPC", "Magick Persistent Cache");
    info->description = "Magick Persistent Cache";
    info->encoder = (MagickImageHandler) WriteMPCImage;
    info->decoder = (MagickImageHandler) ReadMPCImage;
    info->blob_support = MagickTrue;
    info->seekable = MagickTrue;
    info->adjoin = MagickFalse;
    info->page_width = 0;
    info->page_height = 0;
    info->page_x = 0;
    info->page_y = 0;
    info->magick = "MPC";
    info->signature = 0;
    info->flags |= MagickTrue;
    return (size_t) info;
}
